// PRIMARY: crates/trie/sparse/src/trie.rs:reveal_node (lines 529-561)
// When a TrieNode::Leaf is revealed, the key field stores the remaining nibbles:
TrieNode::Leaf(leaf) => match self.nodes.entry(path) {
    Entry::Occupied(mut entry) => match entry.get() {
        SparseNode::Hash(hash) => {
            let mut full = *entry.key();
            full.extend(&leaf.key);  // rest_of_key = leaf.key appended to path
            self.values.insert(full, leaf.value.clone());
            entry.insert(SparseNode::Leaf {
                key: leaf.key,
                hash: Some(*hash),
            });
        }
        SparseNode::Leaf { .. } => {}
        ...
    },
    Entry::Vacant(entry) => {
        let mut full = *entry.key();
        full.extend(&leaf.key);  // leaf.key = key[current_depth:]
        entry.insert(SparseNode::new_leaf(leaf.key));
        self.values.insert(full, leaf.value.clone());
    }
}

