// PRIMARY: crates/ethereum/consensus/src/validation.rs:53-63
// validate_body_against_header checks requests_hash:
if chain_spec.is_prague_active_at_timestamp(block.header().timestamp()) {
    let Some(header_requests_hash) = block.header().requests_hash() else {
        return Err(ConsensusError::RequestsHashMissing)
    };
    let requests_hash = requests.requests_hash();
    if requests_hash != header_requests_hash {
        return Err(ConsensusError::BodyRequestsHashDiff(
            GotExpected::new(requests_hash, header_requests_hash).into(),
        ))
    }
}
// requests_hash() is defined by alloy_consensus via sha256 of concatenated request types.
// Determinism depends on consistent ordering of request types (deposits, withdrawals, consolidations).
